import java.util.Scanner;

public class Main {
    static long countDigits(long n) {
        int count = 0;
        while (n != 0) {
            n /= 10;
            count++;
        }
        return count;
    }

    static long getMaxRepeatingOnes(long n) {
        int digits = (int) countDigits(n);
        long result = 0;
        long powerOfTen = 1;
        for (int i = 0; i < digits; i++) {
            result += powerOfTen;
            powerOfTen *= 10;
        }
        if (result <= n) return result;
        return ((result - 1) / 10);
    }

    static long compute(long n) {
        if (n <= 6) return n;
        if (n <= 11) return 13 - n;
        long base = getMaxRepeatingOnes(n);
        long nextNum = base * 10 + 1;
        if (n % base == 0) {
            if (n <= (nextNum / 2 + base))
                return countDigits(base) * n / base;
            return countDigits(nextNum) + compute(nextNum - n);
        } else {
            long m = (n / base) * base;
            long res = compute(m) + compute(n - m);
            if (n > nextNum / 2)
                res = Math.min(compute(m) + compute(n - m), countDigits(nextNum) + compute(nextNum - n));
            return res;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        System.out.println(compute(n));
        scanner.close();
    }
}
